export function applyRenewal(chapters){for(const [id,data]of Object.entries(renewalData.refine)){const c=chapters.find(c=>c.id===id);c.lessons[0].demo=data.lessons[0].demo;c.lessons.push(...data.lessons);c.missions.unshift(...data.missions);c.refined=true;}const be=chapters.find(c=>c.id==='be1');be.extensionLabel='BE';be.lessons.push(...renewalData.beLessons);be.missions.push(...renewalData.beMissions);for(const extra of renewalData.extras){const after=chapters.findIndex(c=>c.id===(extra.id==='used1'?'c11':'c12'));chapters.splice(after+1,0,extra);}}
